select t.`ctg_id` AS ctgId, t.`ctg_name` AS ctgName, t.`sort_id` AS sortId, t.`ctg_parent_id` AS ctgParentId, t.`is_active` AS isActive, t.`created_by` AS createdBy, DATE_FORMAT(t.`created_time`,'%Y-%m-%d %H:%i:%s') AS createdTime, t.`updated_by` AS updatedBy, DATE_FORMAT(t.`updated_time`,'%Y-%m-%d %H:%i:%s') AS updatedTime from `ssd_query_template_ctg` t where 1=1
and t.is_active = #{isActive}
and t.ctg_name like concat('%', #{ctgNameSearchText},'%')
and t.ctg_name = #{ctgName}
and t.ctg_parent_id = #{ctgParentId}
and t.ctg_id = #{ctgId}
and t.created_by = #{userName}
order by t.`sort_id` asc

select IFNULL(Max(sort_id),0) as sortId
from `ssd_query_template_ctg` t
where 1=1

    and  t.ctg_parent_id = #{ctgParentId}



    and  t.created_by = #{createdBy}

select t.`tpl_id` AS id, t.`tpl_name` AS NAME, t.`tpl_desc` AS description, t.`tpl_config` AS config, t.`created_by` AS createdBy, DATE_FORMAT(t.`created_time`,'%Y-%m-%d %H:%i:%s') AS createdTime, t.`updated_by` AS updatedBy, DATE_FORMAT(t.`updated_time`,'%Y-%m-%d %H:%i:%s') AS updatedTime, t.tpl_exp_max_rows as tplExpMaxRows, t.`ctg_id` AS ctgId, CASE WHEN t.`ctg_id` = 'my' THEN '我的模板' WHEN t.`ctg_id` = 'public' THEN '公共模板' ELSE c.`ctg_name` END AS ctgName
from `ssd_query_template` t left join `ssd_query_template_ctg` c on t.`ctg_id` = c.`ctg_id` where 1=1
and ( t.tpl_name like concat('%', #{templateSearchText},'%') or t.created_by like concat('%', #{templateSearchText},'%') or t.tpl_id = #{templateSearchText} )
and #{userName} in (SELECT m.shared_user_name FROM ssd_query_template_share m where m.tpl_id = t.tpl_id AND m.is_active = 1)
and t.created_by = #{userName}
and ( t.created_by = #{userName} or #{userName} in (SELECT m.shared_user_name FROM ssd_query_template_share m where m.tpl_id = t.tpl_id AND m.is_active = 1) or (t.`ctg_id` = 'public') )
and t.`ctg_id` in
#{item}
order by t.`created_time` desc LIMIT ${pageRowLower}, ${prePageSize}

select count(1) as f_count
from (
    select
        t.`tpl_id`
    from `ssd_query_template` t
    left join `ssd_query_template_ctg` c on t.`ctg_id` = c.`ctg_id`
    where 1=1

            and (
            t.tpl_name like concat('%', #{templateSearchText},'%')
            or
            t.created_by like concat('%', #{templateSearchText},'%')
            or
            t.tpl_id = #{templateSearchText}
            )



                and  #{userName} in (SELECT m.shared_user_name FROM ssd_query_template_share m where m.tpl_id = t.tpl_id AND m.is_active = 1)



                and  t.created_by = #{userName}


                and ( t.created_by = #{userName}
                or
                #{userName} in (SELECT m.shared_user_name FROM ssd_query_template_share m where m.tpl_id = t.tpl_id AND m.is_active = 1)
                or
                (t.`ctg_id` = 'public')
                )





            and  t.`ctg_id` in

                #{item}


    ) tmp

select q.question_id AS questionId, q.object_type AS objectType, q.object_id AS objectId, q.object_title AS objectTitle, q.question_content AS questionContent, q.question_owner AS questionOwner, q.answer_content AS answerContent, q.answer_owner AS answerOwner, q.is_answer AS isAnswer, q.question_time AS questionTime, q.answer_time AS answerTime, q.is_active AS isActive, q.sort_id AS sortId, q.created_time AS createdTime, q.updated_time AS updatedTime, q.created_by AS createdBy, q.updated_by AS updatedBy from `ssd_question_answer` q where 1=1
and q.answer_owner like concat('%', #{answerOwner} ,'%')
and q.question_owner like concat('%', #{questionOwner} ,'%')
and q.object_title like concat('%', #{objectTitle} ,'%')
and q.object_id = #{objectId}
and q.object_type = #{objectType}
and q.is_answer = #{isAnswer}
and q.is_active = #{isActive}
and q.question_time >= #{questionTimeBegin}
and #{questionTimeEnd} >= q.question_time
ORDER BY ${orderBy}
ORDER BY q.sort_id ASC,q.question_time DESC
LIMIT ${pageNum}, ${pageSize}

select count(1) from ( select q.question_id AS questionId, q.object_type AS objectType, q.object_id AS objectId, q.object_title AS objectTitle, q.question_content AS questionContent, q.question_owner AS questionOwner, q.answer_content AS answerContent, q.answer_owner AS answerOwner, q.is_answer AS isAnswer, q.question_time AS questionTime, q.answer_time AS answerTime, q.is_active AS isActive, q.sort_id AS sortId, q.created_time AS createdTime, q.updated_time AS updatedTime, q.created_by AS createdBy, q.updated_by AS updatedBy from `ssd_question_answer` q where 1=1 and q.answer_owner like concat('%', #{answerOwner} ,'%')
and q.question_owner like concat('%', #{questionOwner} ,'%')
and q.object_title like concat('%', #{objectTitle} ,'%')
and q.object_id = #{objectId}
and q.object_type = #{objectType}
and q.is_answer = #{isAnswer}
and q.is_active = #{isActive}
and q.question_time >= #{questionTimeBegin}
and #{questionTimeEnd} >= q.question_time
) a

mapper.update:
update ssd_question_answer
question_owner=#{questionOwner}, question_time=#{questionTime}, question_content=#{questionContent}, answer_content=#{answerContent}, answer_owner=#{answerOwner}, answer_time=#{answerTime}, is_answer=#{isAnswer}, is_active=#{isActive}, updated_by=#{updatedBy}, updated_time = now()
where 1=1 and question_id = #{questionId}

update ssd_question_answer
sort_id=#{sortId}, updated_time = now()
where 1=1 and question_id = #{questionId}

update ssd_query_log
set
    ui_begin_time = #{uiBeginTime},
    ui_end_time = #{uiEndTime}
where log_id = #{id}

mapper.select:
SELECT DISTINCT t.`dim_code` as `key`, cfg.`dim_name` as `value` FROM ssd_field_auth_dim t INNER JOIN bi_portal.sys_data_auth_cfg cfg ON t.`dim_code` = cfg.`dim_code` WHERE t.`field_code` IN
#{item}
AND t.`module_code` = 'ssm_row'

SELECT m.dim_name as `key`, GROUP_CONCAT(DISTINCT m.item_value) as `value` FROM (SELECT t.`owner_id` AS userName, t.`module_code`, t.`dim_code`, t.`item_code`, t.`item_value`, t.`dim_name` FROM bi_portal.sys_data_auth t WHERE t.`owner_type` = 'User' AND t.`module_code` = 'ssm_row' AND t.`owner_id` = #{userName} AND t.created_time > DATE_ADD(CURDATE(), INTERVAL -1* t.active_duration_days DAY)
AND t.`dim_code` in
#{item.DIMCODE}
UNION all SELECT sur.USER_NAME AS userName, t1.`module_code`, t1.`dim_code`, t1.`item_code`, t1.`item_value`, t1.`dim_name` FROM bi_portal.sys_data_auth t1 INNER JOIN bi_portal.sys_user_role sur ON t1.`owner_id` = sur.ROLE_ID WHERE t1.`owner_type` = 'Role' AND t1.`module_code` = 'ssm_row' AND sur.USER_NAME = #{userName} AND sur.created_time > DATE_ADD(CURDATE(), INTERVAL -1* sur.active_duration_days DAY) AND t1.`dim_code` in
#{item.DIMCODE}
) m
group by m.dim_name

