update ssd_query_exp_log
exp_success=#{success}, exp_status=#{status}, exp_info=#{info}, exp_rows=#{rows}, exp_file_ext=#{fileExt}, exp_file_name=#{fileName}, exp_end_time = now()
where 1=1 and exp_id = #{id}

